	public boolean spawn() {
		if (this.isActive()) {
			return false;
		}

		initModel();
		initLocation();
		if (objectToRemove != null) {
			removeOtherObjects();
		}

		if (idleAnimationId != null) {
			setAnimation(idleAnimationId.getId());
		}

		plugin.clientThread.invokeLater(() -> {
			rlObject.setActive(true);
		});

		if (plugin.IS_DEVELOPMENT) {
			plugin.panel.update();
		}

		return true;
	}

